  const n = src.length, act = aS/n, inh = iS/n;
  const bg = (Math.sin(sx*0.04+sy*0.025+t*0.8)*0.5+Math.sin(sx*0.03-sy*0.04+t*1.1)*0.5+Math.sin((sx+sy)*0.12+t*2.5)*0.2+Math.sin((sx-sy)*0.1-t*2)*0.2+Math.sin(sx*0.08+sy*0.06-t*1.5)*0.15+Math.sin(sx*0.05-sy*0.09+t*1.8)*0.15)/1.7;
