  const blend = reaction*0.6+cell*0.25+micro, v = blend*0.5+0.5;
  const pal = [[6,12,52],[12,45,95],[18,85,120],[25,130,135],[45,160,120],[140,180,80],[210,185,55],[225,145,55],[210,105,65],[180,65,75],[130,40,70],[70,22,60],[30,12,50],[6,12,52]];
